  :root {
    --bg: #0b0a09;
    --surface: #161311;
    --surface-2: #1d1815;
    --line: rgba(214, 173, 104, 0.22);
    --line-strong: rgba(214, 173, 104, 0.48);
    --gold: #d6ad68;
    --gold-bright: #f2d6a2;
    --text: #f4eee5;
    --muted: #a89e91;
    --radius: 18px;
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    background:
      radial-gradient(900px 520px at 78% -8%, rgba(214, 173, 104, 0.13), transparent 62%),
      radial-gradient(700px 500px at 4% 32%, rgba(122, 88, 48, 0.10), transparent 60%),
      var(--bg);
    color: var(--text);
    font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", system-ui, sans-serif;
    line-height: 1.75;
    -webkit-font-smoothing: antialiased;
  }
  a { color: inherit; text-decoration: none; }
  .wrap { width: min(1180px, calc(100% - 48px)); margin: 0 auto; }

  /* nav */
  .nav {
    position: sticky; top: 0; z-index: 20;
    backdrop-filter: blur(14px);
    background: rgba(11, 10, 9, 0.78);
    border-bottom: 1px solid var(--line);
  }
  .nav-inner { display: flex; align-items: center; justify-content: space-between; height: 68px; }
  .brand { display: flex; align-items: center; gap: 12px; font-weight: 700; letter-spacing: 0.04em; }
  .brand-mark {
    width: 30px; height: 30px; border-radius: 50%;
    border: 1px solid var(--gold); position: relative;
    box-shadow: 0 0 18px rgba(214, 173, 104, 0.28) inset;
  }
  .brand-mark::after {
    content: ""; position: absolute; inset: 7px; border-radius: 50%;
    background: linear-gradient(135deg, var(--gold-bright), #8d6534);
  }
  .nav-links { display: flex; gap: 28px; font-size: 13px; color: var(--muted); }
  .nav-links a:hover { color: var(--gold-bright); }
  .nav-tag { font-size: 11px; letter-spacing: 0.18em; color: var(--gold); border: 1px solid var(--line); padding: 5px 12px; border-radius: 999px; }

  /* hero */
  .hero { padding: 86px 0 70px; }
  .hero-grid { display: grid; grid-template-columns: 1.02fr 0.98fr; gap: 60px; align-items: center; }
  .eyebrow { font-size: 12px; letter-spacing: 0.26em; color: var(--gold); text-transform: uppercase; margin-bottom: 22px; }
  .hero h1 { font-size: clamp(46px, 6vw, 78px); line-height: 1.08; margin: 0 0 12px; letter-spacing: -0.02em; }
  .hero h1 span { color: var(--gold-bright); }
  .hero-sub { font-size: clamp(19px, 2.2vw, 25px); font-weight: 600; margin: 0 0 22px; }
  .hero-desc { color: var(--muted); font-size: 15.5px; max-width: 560px; margin: 0 0 28px; }
  .chips { display: flex; flex-wrap: wrap; gap: 9px; margin-bottom: 34px; }
  .chip { font-size: 12px; color: var(--gold-bright); border: 1px solid var(--line); background: rgba(214, 173, 104, 0.06); padding: 6px 13px; border-radius: 999px; }
  .actions { display: flex; gap: 14px; flex-wrap: wrap; }
  .btn { display: inline-flex; align-items: center; gap: 8px; padding: 12px 22px; border-radius: 999px; font-size: 14px; font-weight: 600; border: 1px solid transparent; transition: 0.2s ease; }
  .btn-primary { background: linear-gradient(120deg, var(--gold-bright), #b98c4a); color: #1a1208; }
  .btn-primary:hover { filter: brightness(1.08); transform: translateY(-2px); }
  .btn-ghost { border-color: var(--line-strong); color: var(--gold-bright); }
  .btn-ghost:hover { background: rgba(214, 173, 104, 0.08); }
  .hero-visual { position: relative; }
  .hero-visual::before {
    content: ""; position: absolute; inset: 12% 8% 6%; border-radius: 50%;
    background: radial-gradient(circle, rgba(214, 173, 104, 0.22), transparent 65%);
    filter: blur(34px);
  }
  .hero-visual img { position: relative; width: 100%; display: block; border-radius: 26px; border: 1px solid var(--line); box-shadow: 0 30px 80px rgba(0,0,0,0.55); }

  /* sections */
  section { padding: 70px 0; }
  .sec-head { margin-bottom: 38px; }
  .sec-index { font-size: 12px; color: var(--gold); letter-spacing: 0.24em; display: block; margin-bottom: 10px; }
  .sec-head h2 { font-size: clamp(27px, 3.4vw, 39px); margin: 0 0 12px; letter-spacing: -0.01em; }
  .sec-head p { color: var(--muted); max-width: 760px; margin: 0; font-size: 15px; }

  .position-box {
    border: 1px solid var(--line); border-radius: var(--radius);
    background: linear-gradient(135deg, rgba(214,173,104,0.08), rgba(255,255,255,0.015));
    padding: 38px 42px; position: relative; overflow: hidden;
  }
  .position-box::after { content: "\201C"; position: absolute; right: 30px; top: -26px; font-size: 150px; color: rgba(214,173,104,0.08); font-family: Georgia, serif; }
  .position-box h3 { margin: 0 0 12px; font-size: 23px; }
  .position-box p { margin: 0; color: var(--muted); max-width: 880px; }

  .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
  .grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
  .card {
    border: 1px solid var(--line); border-radius: var(--radius);
    background: linear-gradient(160deg, var(--surface-2), var(--surface));
    padding: 28px 26px; transition: transform 0.2s ease, border-color 0.2s ease;
  }
  .card:hover { transform: translateY(-4px); border-color: var(--line-strong); }
  .card-num { font-size: 12px; color: var(--gold); letter-spacing: 0.15em; }
  .card h3 { font-size: 18px; margin: 12px 0 10px; }
  .card p { margin: 0; color: var(--muted); font-size: 14px; }

  .divider { height: 1px; background: linear-gradient(90deg, transparent, var(--line-strong), transparent); margin: 0; }

  /* structure */
  .structure-img-wrap { border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: #0a0807; }
  .structure-img-wrap img { width: 100%; display: block; }
  .caption { color: var(--muted); font-size: 12.5px; margin: 12px 2px 44px; }
  .layer-title { display: flex; align-items: center; gap: 12px; margin: 34px 0 16px; font-size: 17px; font-weight: 700; }
  .layer-title .bar { width: 3px; height: 19px; background: var(--gold); border-radius: 2px; }
  .layer-title .en { font-size: 11px; letter-spacing: 0.14em; color: var(--gold); font-weight: 500; }
  .module-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
  .module { border: 1px solid var(--line); border-radius: 14px; padding: 20px 20px 18px; background: rgba(255,255,255,0.018); }
  .module strong { display: block; font-size: 15px; margin-bottom: 7px; color: var(--gold-bright); }
  .module span { font-size: 13px; color: var(--muted); }

  /* zones */
  .zones { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
  .zone { border: 1px solid var(--line); border-radius: 16px; padding: 26px 22px; background: linear-gradient(160deg, rgba(214,173,104,0.07), transparent); text-align: center; }
  .zone-dot { width: 34px; height: 34px; margin: 0 auto 14px; border-radius: 50%; border: 1px solid var(--gold); position: relative; }
  .zone-dot::after { content: ""; position: absolute; inset: 9px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 14px var(--gold); }
  .zone h3 { margin: 0 0 7px; font-size: 16px; }
  .zone p { margin: 0; color: var(--muted); font-size: 12.5px; }

  /* scenarios */
  .scenario { border-top: 1px solid var(--line); padding: 22px 0; display: grid; grid-template-columns: 180px 1fr; gap: 26px; }
  .scenario:last-child { border-bottom: 1px solid var(--line); }
  .scenario h3 { margin: 0; font-size: 17px; }
  .scenario p { margin: 0; color: var(--muted); font-size: 14.5px; }

  /* spec table */
  .table-wrap { border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  th, td { text-align: left; padding: 15px 22px; border-bottom: 1px solid var(--line); }
  th { color: var(--gold); font-weight: 600; width: 30%; background: rgba(214,173,104,0.04); }
  td { color: var(--muted); }
  tr:last-child th, tr:last-child td { border-bottom: none; }

  .note { color: var(--muted); font-size: 12.5px; border-left: 2px solid var(--gold); padding-left: 14px; margin-top: 22px; }
  footer { border-top: 1px solid var(--line); padding: 32px 0 46px; color: #7f756a; font-size: 12px; display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; }

  @media (max-width: 900px) {
    .hero-grid { grid-template-columns: 1fr; gap: 34px; }
    .hero { padding-top: 56px; }
    .grid-4, .module-grid, .zones { grid-template-columns: repeat(2, 1fr); }
    .nav-links { display: none; }
  }
  @media (max-width: 600px) {
    .wrap { width: min(100% - 32px, 1180px); }
    .grid-2, .grid-4, .module-grid, .zones { grid-template-columns: 1fr; }
    .scenario { grid-template-columns: 1fr; gap: 6px; }
    .position-box { padding: 26px 22px; }
    section { padding: 52px 0; }
  }
  @media print {
    body { background: #fff; color: #111; }
    .nav, .actions { display: none; }
    .card, .module, .zone, .position-box, .table-wrap, .structure-img-wrap { break-inside: avoid; }
  }
